import { registerWebComponents } from '@domg-wc/common';
import { VlDatepickerComponent } from '@domg-wc/components/form';

registerWebComponents([VlDatepickerComponent]);

const datepicker = document.querySelector('#datepicker-default');

// vl-change volgt op elke wijziging van de waarde, ook door code; vl-input enkel op invoer van de gebruiker; vl-valid
// op een wijziging waarna de waarde geldig is. event.detail.value is de waarde in ISO-formaat, bv. '2023-12-31'
// (type date); zolang de invoer onvolledig is, is het de tekst uit het invoerveld.
datepicker.addEventListener('vl-change', (event) => console.log('vl-change', event.detail.value));
datepicker.addEventListener('vl-input', (event) => console.log('vl-input', event.detail.value));
datepicker.addEventListener('vl-valid', (event) => console.log('vl-valid', event.detail.value));

// vl-reset volgt op resetFormControl(), die ook loopt als de form gereset wordt (zie Publieke methodes); het event
// heeft geen detail.
datepicker.addEventListener('vl-reset', () => console.log('vl-reset'));
